mapper.select:
SELECT * FROM life_energy_logs
ORDER BY log_date DESC
LIMIT #{limit}

mapper.update:
UPDATE life_energy_logs
SET planned_minutes = #{plannedMinutes}, overload = #{overload}
WHERE id = #{id}

UPDATE life_energy_logs
SET planned_minutes = #{plannedMinutes}, capacity_minutes = #{capacityMinutes}, overload = #{overload},
    distractions = #{distractions}, sleep_hours = #{sleepHours}, health = #{health}, note = #{note}
WHERE id = #{id}
